"""Prepare the reference-inspired spectral carapace model independently of the earlier robes."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]; TOOLS=ROOT/'tools/art_pipeline'
OLD='veil_archon_blocky_v2'; NEW='veil_archon_blocky_v3'
def read(name): return (TOOLS/name).read_text(encoding='utf-8')
def names(s): return s.replace(OLD,NEW).replace('Veil_Archon_Blocky_V2','Veil_Archon_Blocky_V3').replace('VeilArchonModelReviewV2','VeilArchonModelReviewV3')
def write(name,s): (TOOLS/name).write_text(s,encoding='utf-8')
src=read('build_veil_archon_blocky_v2_mcp.py')
head=names(src[:src.index('# A faceless arcane sovereign:')])
head=head.replace('old_hashes={',"protected.extend(ROOT/'assets/generated/grand_manifestations/veil_archon_blocky_v2'/('veil_archon_blocky_v2.'+ext) for ext in ('glb','blend'))\nold_hashes={")
head=head.replace('Three-meter empty ceremonial sovereign of Arcanism, an exposed azure cube and a fractured gate.','Reference-inspired spectral sovereign with black crescent carapaces and an exposed azure cube core.')
uv=src[src.index('coords=[v.co for o in parts for v in o.data.vertices]'):src.index('# Restrained cloth folds')]
uv=uv.replace('blue ceremonial cloth, silver and azure mana','black stone, spectral blue bone and azure mana')
tail=names(src[src.index('images=[]'):]).replace('Sovereign_Cowl_Folded_Veil_Azure_Core','Obsidian_Spectral_Bone_Azure_Core')
tail=tail.replace('Static Veil Archon: exposed azure core in a pointed open cowl, sloped silver ceremonial shoulders, folded midnight-blue mantle, plain square floating hands and a restrained fractured portal.','Static reference-inspired Veil Archon: massive fractured black carapaces, exposed spectral ribs, a small cubic skull, suspended blades, mana wisps and a separate azure cube core.')
tail=tail.replace('Three-meter Veil Archon of Arcanism: faceless pointed cowl framing one azure cube, sculpted silver shoulders, folded midnight-blue robe with an irregular floating hem, plain suspended square hands and a darker engraved portal. Shared by civilizations.','Three-meter Veil Archon following the supplied reference: black fractured crescent shields and blades around a spectral rib cage, current-game cubic skull, exposed azure mana cube, blue inner facets and suspended lower wisps. Shared by civilizations.')
tail=tail.replace('data.ortho_scale=4.5','data.ortho_scale=4.8')
write('build_veil_archon_blocky_v3_mcp.py',head+read('veil_archon_v3_geometry.py')+'\n'+uv+read('veil_archon_v3_texture.py')+'\n'+tail)
export=names(read('export_veil_archon_blocky_v2_mcp.py')).replace("'revision':2","'revision':3")
export=export.replace('A ceremonial sovereign of folded space: pointed open cowl framing an exposed azure cube, sculpted silver shoulders, folded midnight-blue robe, an irregular floating hem, plain square hands and a restrained fractured dimensional gate.','Reference-inspired spectral sovereign: massive black crescent carapaces, fractured suspended blades and pelvic brackets, exposed blue ribs and spine, current-game cubic skull, blue inner facets, lower mana wisps and one exposed azure cube core.')
export=export.replace('Single exposed emissive azure cube, separate rigid pivot within the pointed open cowl','Single exposed emissive azure cube, separate rigid pivot in front of the spectral chest')
export=export.replace("'references':[", "'references':['User-supplied spectral skeleton and black fractured carapace reference',")
export=export.replace("'references':['User-supplied", "'references':['assets/generated/skeletons/skeleton_warrior_v1','User-supplied")
write('export_veil_archon_blocky_v3_mcp.py',export)
for old,new in [('validate_veil_archon_blocky_v2.py','validate_veil_archon_blocky_v3.py'),('verify_veil_archon_blocky_v2.gd','verify_veil_archon_blocky_v3.gd'),('finalize_veil_archon_blocky_v2_mcp.py','finalize_veil_archon_blocky_v3_mcp.py')]: write(new,names(read(old)))
review=names((ROOT/'scripts/art_review/VeilArchonModelReviewV2.gd').read_text(encoding='utf-8')).replace('camera.size = 4.5','camera.size = 4.8')
(ROOT/'scripts/art_review/VeilArchonModelReviewV3.gd').write_text(review,encoding='utf-8')
scene=names((ROOT/'scenes/art_review/VeilArchonModelReviewV2.tscn').read_text(encoding='utf-8'))
(ROOT/'scenes/art_review/VeilArchonModelReviewV3.tscn').write_text(scene,encoding='utf-8')
gallery=names(read('write_veil_archon_v2_review.py'))
gallery=gallery.replace('Uma entidade flutuante com capuz aberto, ombros cerimoniais de prata e um manto azul-escuro com dobras e barra irregular. O núcleo cúbico azul ocupa a abertura do capuz; mãos quadradas simples e fragmentos de portal completam sua silhueta. A figura segue a identidade do Arcanismo: espaço, teleporte e interferência mágica.','Uma entidade espectral cercada por grandes carapaças negras quebradas. Costelas e coluna de energia azul ficam expostas, com um crânio cúbico pequeno acima do núcleo de mana. Lâminas suspensas, facetas azuis e poucos fragmentos grandes seguem a referência enviada, com bordas em degraus e faces planas no estilo blocky do jogo.')
gallery=gallery.replace('Manto azul-escuro com dobras e barra irregular, capuz aberto sem rosto, placas de ombro cerimoniais em prata, mãos quadradas suspensas, núcleo cúbico azul exposto e um portal dimensional fragmentado.','Carapaças negras fragmentadas, lâminas suspensas, costelas e coluna espectrais azuis, crânio cúbico do estilo do esqueleto atual, núcleo cúbico azul exposto e filamentos de mana abaixo do corpo.')
gallery=gallery.replace('A paleta azul e prata vem do arcanista atual.','A referência principal é a entidade espectral enviada pelo usuário. O azul mantém a identidade arcana; o crânio usa os motivos do esqueleto atual.')
gallery=gallery.replace('A paleta segue o arcanista humano atual; o conceito segue os feitiços de mobilidade e interferência da escola.','A estrutura e a silhueta seguem a referência enviada; o crânio respeita a estética atual do jogo, e o núcleo mantém a identidade azul do Arcanismo.')
gallery=gallery.replace('da geometria real do manto, da coroa e do portal','da geometria real das carapaças, das costelas e das lâminas')
gallery=gallery.replace('a geometria real do manto, da coroa e do portal','a geometria real das carapaças, das costelas e das lâminas')
gallery=gallery.replace('Giro completo do núcleo conferido contra as peças sólidas','Giro completo do núcleo conferido contra as carapaças, os ossos e as lâminas')
write('write_veil_archon_v3_review.py',gallery)
write('compare_veil_archon_v3.py',names(read('compare_veil_archon_v2.py')))
print('Reference-inspired black spectral Arconte V3 pipeline prepared.')
